        const accum = await accp;
        const ec2Client = new EC2Client({ credentials: creds, region });
        const snapshots = [];
        let next: string;
        do {
            const response = await ec2Client.send(new DescribeSnapshotsCommand({ Filters, OwnerIds: ['self'] }));
