    # `ExternalId` is constrained to 2..1224 characters. A caller that always
    # sends the parameter and fills it with a blank when it has nothing is
    # rejected before the trust policy is ever consulted, exactly as it is by
    # the real service; omitting the parameter is the only way to say "none".
    if external_id is not None and not 2 <= len(external_id) <= 1224:
        return error_xml(
            "ValidationError",
            f"1 validation error detected: Value '{external_id}' at 'externalId' failed to satisfy "
            "constraint: Member must have length greater than or equal to 2 and less than or equal to 1224",
            400,
        )

    parts = role_arn.split(":")
    if len(parts) < 6 or parts[2] != "iam":
        return error_xml("ValidationError", f"Invalid RoleArn: {role_arn}", 400)
    account_id = parts[4]
    account = world.account(account_id)
    if account is None:
        return error_xml("AccessDenied", f"Not authorized to perform sts:AssumeRole on {role_arn}", 403)
    role = account.find_role_by_arn(role_arn)
