import { BadRequestException, Logger } from '@nestjs/common';
import { STSClient, AssumeRoleCommand } from '@aws-sdk/client-sts';
import { EC2Client, DescribeInstancesCommand } from '@aws-sdk/client-ec2';
import { serializeError } from 'serialize-error';

const logger = new Logger('verifyScraperRole');

/**
 * Proves, before a customer's scraper role is persisted, that:
 *   1. the role can actually be assumed with the supplied external id, and
 *   2. the temporary credentials that assumption returns can read the EC2
 *      instance inventory that collection relies on.
 *
 * Either check failing is a bad request; the caller must abort the save so that
 * nothing else in that update is written.
 */
export const verifyScraperRole = async ({
    iamRoleArn,
    externalId,
}: {
    iamRoleArn: string;
    externalId?: string;
}): Promise<void> => {
    const region = process.env.AWS_REGION || 'us-east-1';

    // 1. Prove the role can be assumed with the supplied external id.
    let credentials;
    try {
        const sts = new STSClient({ region });
        const { Credentials } = await sts.send(
            new AssumeRoleCommand({
                RoleArn: iamRoleArn,
                RoleSessionName: 'meteringco-scraper-verification',
                ExternalId: externalId ? externalId : undefined,
            }),
        );
        credentials = Credentials;
        if (!credentials?.AccessKeyId || !credentials?.SecretAccessKey) {
            throw new Error('AssumeRole returned no usable credentials');
        }
    } catch (e) {
        logger.error(`Unable to assume scraper role ${iamRoleArn}: ${JSON.stringify(serializeError(e))}`);
        throw new BadRequestException(
            'Unable to assume the provided IAM role with the supplied external ID',
        );
    }

    // 2. Prove the returned credentials can read the instance inventory used by collection.
    try {
        const ec2 = new EC2Client({
            region,
            credentials: {
                accessKeyId: credentials.AccessKeyId,
                secretAccessKey: credentials.SecretAccessKey,
                sessionToken: credentials.SessionToken,
            },
        });
        await ec2.send(new DescribeInstancesCommand({ MaxResults: 5 }));
    } catch (e) {
        logger.error(
            `Scraper role ${iamRoleArn} cannot read the EC2 instance inventory: ${JSON.stringify(
                serializeError(e),
            )}`,
        );
        throw new BadRequestException(
            'The provided IAM role cannot read the EC2 instance inventory used for collection',
        );
    }
};
